import tensorcircuit as tc
import numpy as np
import time

tc.set_backend('numpy')
tc.set_dtype('complex128')

n = 12
dim = 2 ** n
angle = 0.31
U = np.asarray(tc.gates.rxx(theta=angle).tensor, dtype=np.complex128).reshape(4, 4)
print('U ok', U.shape)

def kraus(p01, p10):
    K0 = np.array([[np.sqrt(1-p01), 0], [0, np.sqrt(1-p10)]], dtype=np.complex128)
    K1 = np.array([[0, np.sqrt(p10)], [0, 0]], dtype=np.complex128)
    K2 = np.array([[0, 0], [np.sqrt(p01), 0]], dtype=np.complex128)
    return [K0, K1, K2]

def apply_unitary_2q(rho, U4, q1, q2):
    # rho: (dim,dim)
    left = 2 ** q1
    mid = 2 ** (q2 - q1 - 1)
    right = 2 ** (n - q2 - 1)
    r = rho.reshape(left, 2, mid, 2, right, left, 2, mid, 2, right)
    # bring ket qubits together and bra qubits together
    # shape to (left*mid*right, 4, left*mid*right, 4)
    r = np.transpose(r, (0, 2, 4, 1, 3, 5, 7, 9, 6, 8))
    # (L,M,R, k1,k2, L,M,R, b1,b2)
    r = r.reshape(left*mid*right, 4, left*mid*right, 4)
    r = np.einsum('ij,ajbk,lk->ailb', U4, r, np.conj(U4), optimize=True)
    r = r.reshape(left, mid, right, 2, 2, left, mid, right, 2, 2)
    r = np.transpose(r, (0, 3, 1, 4, 2, 5, 8, 6, 9, 7))
    return r.reshape(dim, dim)

def apply_channel_1q(rho, Ks, q):
    left = 2 ** q
    right = 2 ** (n - q - 1)
    r = rho.reshape(left, 2, right, left, 2, right)
    r = np.transpose(r, (0, 2, 1, 3, 5, 4))  # L R k L R b
    r = r.reshape(left*right, 2, left*right, 2)
    out = np.zeros_like(r)
    for K in Ks:
        out += np.einsum('ij,ajbk,lk->ailb', K, r, np.conj(K), optimize=True)
    out = out.reshape(left, right, 2, left, right, 2)
    out = np.transpose(out, (0, 2, 1, 3, 5, 4))
    return out.reshape(dim, dim)

def init_rho(kind):
    psi = np.zeros(dim, dtype=np.complex128)
    if kind == 0:
        psi[0] = 1/np.sqrt(2); psi[-1]=1/np.sqrt(2)
    elif kind == 1:
        psi = np.array([1.0], dtype=np.complex128)
        s = 1/np.sqrt(2)
        for _ in range(n//2):
            a = np.zeros(psi.size*4, dtype=np.complex128)
            a[1::4] = psi*s
            a[2::4] = psi*s
            psi = a
    elif kind == 2:
        psi[0] = 1
    else:
        psi[:] = 1/np.sqrt(dim)
    return np.outer(psi, np.conj(psi))

def expects(rho):
    diag = np.real(np.diag(rho))
    outs = []
    idx = np.arange(dim)
    for q in range(n):
        signs = 1 - 2*((idx >> (n-1-q)) & 1)
        outs.append(diag @ signs)
    parity = np.zeros(dim, np.int64)
    x = idx.copy()
    for _ in range(n):
        parity ^= x & 1
        x >>= 1
    outs.append(diag @ (1-2*parity))
    return np.array(outs)

def evolve(kind, p01, p10):
    rho = init_rho(kind)
    Ks = kraus(p01, p10)
    for i in range(0, n-1, 2):
        rho = apply_unitary_2q(rho, U, i, i+1)
        rho = apply_channel_1q(rho, Ks, i)
        rho = apply_channel_1q(rho, Ks, i+1)
    for i in range(1, n-1, 2):
        rho = apply_unitary_2q(rho, U, i, i+1)
        rho = apply_channel_1q(rho, Ks, i)
        rho = apply_channel_1q(rho, Ks, i+1)
    return expects(rho)

# validate vs DMCircuit
def ref(kind, p01, p10):
    c=tc.DMCircuit(n)
    if kind==0:
        c.h(0)
        for i in range(n-1): c.cnot(i,i+1)
    elif kind==1:
        for i in range(0,n,2):
            c.x(i+1); c.h(i); c.cnot(i,i+1)
    elif kind==3:
        for i in range(n): c.h(i)
    Ks=kraus(p01,p10)
    for i in range(0,n-1,2):
        c.rxx(i,i+1,theta=angle); c.apply_general_kraus(Ks,i); c.apply_general_kraus(Ks,i+1)
    for i in range(1,n-1,2):
        c.rxx(i,i+1,theta=angle); c.apply_general_kraus(Ks,i); c.apply_general_kraus(Ks,i+1)
    rho=np.array(c.state(),dtype=np.complex128)
    return expects(rho)

for kind in range(4):
    t0=time.time(); v=evolve(kind,0.034,0.011); t1=time.time()
    r=ref(kind,0.034,0.011)
    print(kind, 'time', t1-t0, 'diff', np.max(np.abs(v-r)))

