def apply_2q_fast(rho, U4, q1, q2):
    # Move qubits q1,q2 to positions at LSB via bit tricks - use reshape hierarchy
    # General adjacent only for our circuit: q2=q1+1
    assert q2 == q1+1
    left = 2**q1
    right = 2**(n-q2-1)
    # rho shape (left, 4, right, left, 4, right)
    r = rho.reshape(left, 4, right, left, 4, right)
    # apply U on axis 1, U* on axis 4
    # r' [a,i,b,c,j,d] = sum_{k,l} U[i,k] r[a,k,b,c,l,d] conj(U[j,l])
    r = np.tensordot(U4, r, axes=([1],[1]))  # (i, a, b, c, l, d) 
    r = np.moveaxis(r, 0, 1)  # (a,i,b,c,l,d)
    r = np.tensordot(r, np.conj(U4).T, axes=([4],[0]))  # (a,i,b,c,d,j) where sum_l r[..l..] conj(U).T[l,j]=conj(U)[j,l]
    # wait conj(U).T[l,j] = conj(U)[j,l] yes
    r = np.moveaxis(r, -1, 4)  # (a,i,b,c,j,d)
    return r.reshape(dim,dim)

def apply_1q_channel_fast(rho, Ks, q):
    left=2**q; right=2**(n-q-1)
    r = rho.reshape(left, 2, right, left, 2, right)
    out = np.zeros_like(r)
    for K in Ks:
        t = np.tensordot(K, r, axes=([1],[1])) # (i,a,b,c,l,d)
        t = np.moveaxis(t, 0, 1) # a i b c l d
        t = np.tensordot(t, np.conj(K).T, axes=([4],[0])) # a i b c d j
        t = np.moveaxis(t, -1, 4)
        out += t
    return out.reshape(dim,dim)

