import jax
import jax.numpy as jnp
import numpy as np
import time

tc.set_backend('jax')
tc.set_dtype('complex64')
n=12
angle=0.31

def make_kraus(p01, p10):
    K0 = jnp.array([[jnp.sqrt(1-p01), 0],[0, jnp.sqrt(1-p10)]], dtype=jnp.complex64)
    K1 = jnp.array([[0, jnp.sqrt(p10)],[0,0]], dtype=jnp.complex64)
    K2 = jnp.array([[0,0],[jnp.sqrt(p01),0]], dtype=jnp.complex64)
    return [K0,K1,K2]

def one_row(p01, p10, kind):
    c = tc.DMCircuit(n)
    if kind == 0:
        c.h(0)
        for i in range(n-1):
            c.cnot(i,i+1)
    elif kind == 1:
        for i in range(0,n,2):
            c.x(i+1); c.h(i); c.cnot(i,i+1)
    elif kind == 3:
        for i in range(n):
            c.h(i)
    k = make_kraus(p01, p10)
    for i in range(0,n-1,2):
        c.rxx(i,i+1,theta=angle)
        c.apply_general_kraus(k, i)
        c.apply_general_kraus(k, i+1)
    for i in range(1,n-1,2):
        c.rxx(i,i+1,theta=angle)
        c.apply_general_kraus(k, i)
        c.apply_general_kraus(k, i+1)
    outs = []
    for i in range(n):
        outs.append(jnp.real(c.expectation_ps(z=[i])))
    outs.append(jnp.real(c.expectation_ps(z=list(range(n)))))
    return jnp.stack(outs)

