    p01 = jax.nn.sigmoid(params[0])
    p10 = jax.nn.sigmoid(params[1])
    return jnp.stack([one_row(p01,p10,k) for k in range(4)], axis=0)

def loss(params, target):
    pred = table(params)
    return jnp.mean((pred-target)**2)

