import tensorcircuit as tc
import numpy as np
from collections import defaultdict
import time

tc.set_backend('numpy')
n=12
angle=0.31
I=np.eye(2,dtype=np.complex128)
X=np.array([[0,1],[1,0]],np.complex128)
Y=np.array([[0,-1j],[1j,0]],np.complex128)
Z=np.array([[1,0],[0,-1]],np.complex128)
P1=[I,X,Y,Z]

def channel_dual_ptm(p01,p10):
    Ks=[
        np.array([[np.sqrt(1-p01),0],[0,np.sqrt(1-p10)]],np.complex128),
        np.array([[0,np.sqrt(p10)],[0,0]],np.complex128),
        np.array([[0,0],[np.sqrt(p01),0]],np.complex128),
    ]
    R=np.zeros((4,4),np.complex128)
    for b in range(4):
        Op=sum(K.conj().T@P1[b]@K for K in Ks)
        for a in range(4):
            R[a,b]=np.trace(P1[a]@Op)/2
    return np.real(R)

def rxx_dual_ptm():
    U=np.asarray(tc.gates.rxx(theta=angle).tensor,np.complex128).reshape(4,4)
    P2=[np.kron(P1[i],P1[j]) for i in range(4) for j in range(4)]
    R=np.zeros((16,16),np.complex128)
    for b,Pb in enumerate(P2):
        Op=U.conj().T@Pb@U
        for a,Pa in enumerate(P2):
            R[a,b]=np.trace(Pa@Op)/4
    return np.real(R)

R2=rxx_dual_ptm()
R1=channel_dual_ptm(0.034,0.011)
print('R1\n',R1)

def apply_1q(op,q,R):
    new=defaultdict(complex)
    for s,c in op.items():
        b=s[q]
        for a in range(4):
            v=R[a,b]
            if abs(v)<1e-15: continue
            ns=list(s); ns[q]=a
            new[tuple(ns)] += c*v
    return {k:v for k,v in new.items() if abs(v)>1e-15}

def apply_2q(op,q1,q2,R):
    new=defaultdict(complex)
    for s,c in op.items():
        bin=4*s[q1]+s[q2]
        col=R[:,bin]
        for aout,val in enumerate(col):
            if abs(val)<1e-15: continue
            a1,a2=divmod(aout,4)
            ns=list(s); ns[q1]=a1; ns[q2]=a2
